body {
background-color: #000000;
display: flex;
justify-content: center;
align-items: flex-start;
padding-top: 140px;
min-height: 100vh;
overflow: hidden;
}
.wrapper {
position: relative;
width: 130px;
}
.trigger {
width: 100%;
display: flex;
justify-content: space-between;
align-items: center;
height: 36px;
cursor: pointer;
border-radius: 18px;
padding: 0 14px;
font-size: 14px;
font-weight: 500;
letter-spacing: -0.2px;
background: var(--surface);
border: 1px solid var(--border);
color: var(--fg);
box-shadow: inset 0 1px 1px var(--surface-hi), 0 4px 16px rgba(0, 0, 0, 0.4);
backdrop-filter: blur(40px) saturate(150%);
-webkit-backdrop-filter: blur(40px) saturate(150%);
outline: none;
transition: background-color 0.3s ease, transform 0.2s cubic-bezier(0.32, 0.72, 0, 1);
}
.trigger:active {
transform: scale(0.96);
background: var(--hover);
}
.chevron {
width: 16px;
height: 16px;
color: var(--fg2);
transition: transform 0.4s cubic-bezier(0.32, 0.72, 0, 1), color 0.3s ease;
}
.trigger.open .chevron {
transform: rotate(180deg);
color: var(--fg);
}
.popover {
position: absolute;
top: calc(100% + 8px);
left: 0;
width: 100%;
z-index: 50;
border-radius: 16px;
border: 1px solid var(--border);
background: var(--surface);
box-shadow: inset 0 1px 1px var(--surface-hi), 0 12px 32px rgba(0, 0, 0, 0.6);
backdrop-filter: blur(40px) saturate(150%);
-webkit-backdrop-filter: blur(40px) saturate(150%);
padding: 4px;
opacity: 0;
transform: scale(0.96) translateY(-6px);
pointer-events: none;
transition: opacity 0.3s cubic-bezier(0.32, 0.72, 0, 1), transform 0.3s cubic-bezier(0.32, 0.72, 0, 1);
display: flex;
flex-direction: column;
gap: 2px;
}
.popover.open {
opacity: 1;
transform: scale(1) translateY(0);
pointer-events: auto;
}
.item {
position: relative;
display: flex;
align-items: center;
height: 32px;
cursor: pointer;
border-radius: 12px;
padding: 0 10px;
font-size: 13px;
font-weight: 500;
letter-spacing: -0.1px;
color: var(--fg);
overflow: hidden;
background: transparent;
transition: background-color 0.2s ease;
}
.item:active:not(.animating) {
background: var(--hover);
}
.item-text {
position: relative;
z-index: 2;
}
.fill-layer {
position: absolute;
top: 0;
left: 0;
width: 100%;
height: 100%;
z-index: 1;
opacity: 0;
pointer-events: none;
clip-path: inset(0 100% 0 0);
filter: blur(4px);
transform: scale(1.05);
}
.item[data-value="Model"] .fill-layer {
background: var(--model-grad);
}
.item[data-value="Agent"] .fill-layer {
background: var(--agent-grad);
}
.item.animating .fill-layer {
animation: etherealFill 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}
@keyframes etherealFill {
0% { clip-path: inset(0 100% 0 0); opacity: 0; }
15% { opacity: 1; }
40% { clip-path: inset(0 0 0 0); opacity: 1; }
70% { clip-path: inset(0 0 0 0); opacity: 1; }
100% { clip-path: inset(0 0 0 0); opacity: 0; }
}
</style>
</head>
<body>
<div class="wrapper">
<button id="trigger" class="trigger">
<span id="trigger-text">Model</span>
<svg class="chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
<polyline points="6 9 12 15 18 9"></polyline>
</svg>
</button>
<div id="popover" class="popover">
<div class="item" data-value="Model">
<span class="item-text">Model</span>
<div class="fill-layer"></div>
</div>
<div class="item" data-value="Agent">
<span class="item-text">Agent</span>
<div class="fill-layer"></div>
</div>
</div>
</div>
<script>
const trigger = document.getElementById('trigger');
const popover = document.getElementById('popover');
const triggerText = document.getElementById('trigger-text');
const items = document.querySelectorAll('.item');
let isAnimating = false;
function triggerHaptic() {
if (window.ReactNativeWebView) {
window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'selection' }));
} else if (navigator.vibrate) {
navigator.vibrate(30);
}
}
trigger.addEventListener('click', (e) => {
e.stopPropagation();
if (isAnimating) return;
triggerHaptic();
trigger.classList.toggle('open');
popover.classList.toggle('open');
});
document.addEventListener('click', (e) => {
if (!popover.contains(e.target) && !trigger.contains(e.target) && popover.classList.contains('open')) {
trigger.classList.remove('open');
popover.classList.remove('open');
}
});
items.forEach(item => {
item.addEventListener('click', (e) => {
e.stopPropagation();
if (isAnimating) return;
isAnimating = true;
triggerHaptic();
item.classList.add('animating');
setTimeout(() => {
triggerText.textContent = item.getAttribute('data-value');
trigger.classList.remove('open');
popover.classList.remove('open');
}, 650);
setTimeout(() => {
item.classList.remove('animating');
isAnimating = false;
}, 950);
});
});
</script>
</body>
</html>


