<script>
(function(){
const trigger = document.getElementById('trigger');
const popover = document.getElementById('popover');
const triggerLabel = document.getElementById('trigger-label');
const items = popover.querySelectorAll('.item');
let busy = false;
let selected = 'Model';
let isOpen = false;

function haptic(type) {
if (window.ReactNativeWebView) {
window.ReactNativeWebView.postMessage(JSON.stringify({ type: type || 'selection' }));
} else if (navigator.vibrate) {
navigator.vibrate(type === 'open' ? [6] : [8]);
}
}

function openPopover() {
isOpen = true;
trigger.classList.add('open');
trigger.setAttribute('aria-expanded', 'true');
popover.classList.add('open');
haptic('open');
}

function closePopover() {
isOpen = false;
trigger.classList.remove('open');
trigger.setAttribute('aria-expanded', 'false');
popover.classList.remove('open');
}

function spawnRipple(el, x, y) {
const rect = el.getBoundingClientRect();
const size = Math.max(rect.width, rect.height);
const r = document.createElement('div');
r.className = 'ripple-circle';
r.style.cssText = 'width:' + size + 'px;height:' + size + 'px;left:' + (x - rect.left - size/2) + 'px;top:' + (y - rect.top - size/2) + 'px;';
el.appendChild(r);
r.addEventListener('animationend', () => r.remove());
}

function setSelected(value) {
selected = value;
triggerLabel.textContent = value;
items.forEach(function(item) {
const v = item.getAttribute('data-value');
const isSel = v === value;
item.classList.toggle('selected', isSel);
item.setAttribute('aria-selected', isSel ? 'true' : 'false');
});
}

trigger.addEventListener('click', function(e) {
e.stopPropagation();
if (busy) return;
if (isOpen) {
closePopover();
} else {
openPopover();
}
});

trigger.addEventListener('touchstart', function(e) {
trigger.style.transform = 'scale(0.94)';
}, { passive: true });

trigger.addEventListener('touchend', function() {
trigger.style.transform = '';
}, { passive: true });

items.forEach(function(item) {
item.addEventListener('click', function(e) {
e.stopPropagation();
if (busy) return;
const value = item.getAttribute('data-value');
if (value === selected) {
closePopover();
return;
}
busy = true;
haptic('selection');
const touch = e.changedTouches ? e.changedTouches[0] : e;
spawnRipple(item, touch.clientX || e.clientX, touch.clientY || e.clientY);
item.classList.add('rippling');
item.addEventListener('animationend', function handler() {
item.classList.remove('rippling');
item.removeEventListener('animationend', handler);
}, { once: true });
setTimeout(function() {
setSelected(value);
closePopover();
}, 200);
setTimeout(function() {
busy = false;
}, 500);
});

item.addEventListener('touchstart', function() {
item.style.background = 'var(--active)';
}, { passive: true });

item.addEventListener('touchend', function() {
item.style.background = '';
}, { passive: true });

item.addEventListener('touchcancel', function() {
item.style.background = '';
}, { passive: true });
});

document.addEventListener('click', function(e) {
if (isOpen && !popover.contains(e.target) && !trigger.contains(e.target)) {
closePopover();
}
});

document.addEventListener('touchstart', function(e) {
if (isOpen && !popover.contains(e.target) && !trigger.contains(e.target)) {
closePopover();
}
}, { passive: true });

document.addEventListener('keydown', function(e) {
if (e.key === 'Escape' && isOpen) closePopover();
});
})();
</script>
